const TRANSLATION_SUFFIX_RE = /\s+(?:NIV|ESV|KJV|NKJV|NLT|CSB|NASB)$/i;
const MS_PER_DAY = 86400000;
const yearPermutationCache = new Map();

export function getVerseIdFromTag(tag) {
  if (!tag || typeof tag !== "string") return "";
  return tag
    .trim()
    .replace(TRANSLATION_SUFFIX_RE, "")
    .trim()
    .replace(/[\s:]+/g, "_");
}

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function getDaysInYear(year) {
  return isLeapYear(year) ? 366 : 365;
}

function mulberry32(seed) {
  let a = seed >>> 0;
  return function nextRandom() {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function buildBasePermutation(year) {
  const seed = (Math.imul(year | 0, 0x9e3779b1) ^ 0x85ebca6b) >>> 0;
  const rand = mulberry32(seed);
  const perm = Array.from({ length: verses.length }, (_, i) => i);
  for (let i = perm.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const tmp = perm[i];
    perm[i] = perm[j];
    perm[j] = tmp;
  }
  return perm;
}

function getYearPermutation(year) {
  const cached = yearPermutationCache.get(year);
  if (cached) return cached;

  const perm = buildBasePermutation(year);
  const prevPerm = buildBasePermutation(year - 1);
  const prevDays = getDaysInYear(year - 1);
  const prevLast7 = new Set(prevPerm.slice(prevDays - 7, prevDays));

  // Only swap into middle indices strictly before this year's final 7 days
  // so year + 1 inspecting buildBasePermutation(year) sees identical tail elements.
  const thisDays = getDaysInYear(year);
  const midEnd = Math.min(perm.length - 1, thisDays - 8);
  const midStart = Math.max(7, Math.min(Math.floor(perm.length / 2), midEnd - 30));
  let swapCursor = midStart;

  for (let i = 0; i < 7 && i < perm.length; i++) {
    if (prevLast7.has(perm[i])) {
      while (swapCursor <= midEnd && prevLast7.has(perm[swapCursor])) {
        swapCursor++;
      }
      if (swapCursor <= midEnd) {
        const tmp = perm[i];
        perm[i] = perm[swapCursor];
        perm[swapCursor] = tmp;
        swapCursor++;
      }
    }
  }

  yearPermutationCache.set(year, perm);
  return perm;
}

export function getVerseOfTheDay(date = new Date(), options = {}) {
  const parsed = date instanceof Date ? date : new Date(date);
  const validDate = !Number.isNaN(parsed.getTime()) ? parsed : new Date();
  const useUtc = Boolean(options?.useUtc);

  const year = useUtc ? validDate.getUTCFullYear() : validDate.getFullYear();
  const month = useUtc ? validDate.getUTCMonth() : validDate.getMonth();
  const day = useUtc ? validDate.getUTCDate() : validDate.getDate();

  const dayOfYear = Math.round(
    (Date.UTC(year, month, day) - Date.UTC(year, 0, 0)) / MS_PER_DAY
  );

  const perm = getYearPermutation(year);
  const pos = (((dayOfYear - 1) % perm.length) + perm.length) % perm.length;
  const index = perm[pos];
  const entry = verses[index] || verses[0];

  return {
    verse: entry.verse,
    tag: entry.tag,
    id: getVerseIdFromTag(entry.tag),
    index,
    dayOfYear,
    year,
  };
}

export function getRecentVerses(count = 6, date = new Date(), options = {}) {
  const parsed = date instanceof Date ? date : new Date(date);
  const validDate = !Number.isNaN(parsed.getTime()) ? parsed : new Date();
  const useUtc = Boolean(options?.useUtc);

  const year = useUtc ? validDate.getUTCFullYear() : validDate.getFullYear();
  const month = useUtc ? validDate.getUTCMonth() : validDate.getMonth();
  const day = useUtc ? validDate.getUTCDate() : validDate.getDate();

  const recent = [];
  const total = Math.max(0, Number.isFinite(count) ? Math.floor(count) : 6);
  for (let i = 1; i <= total; i++) {
    const d = useUtc
      ? new Date(Date.UTC(year, month, day - i))
      : new Date(year, month, day - i, 12, 0, 0);
    const votd = getVerseOfTheDay(d, options);
    const label = d.toLocaleDateString("en-US", {
      weekday: "long",
      month: "short",
      day: "numeric",
      ...(useUtc ? { timeZone: "UTC" } : {}),
    });
    recent.push({
      verse: { verse: votd.verse, tag: votd.tag },
      id: votd.id,
      label,
    });
  }
  return recent;
}
